import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Скрипты Lua","description":"","frontmatter":{},"headers":[],"relativePath":"ru/development/lua/index.md","filePath":"ru/development/lua/index.md","lastUpdated":1791683719000}`),a={name:`ru/development/lua/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="скрипты-lua" tabindex="-1">Скрипты Lua <a class="header-anchor" href="#скрипты-lua" aria-label="Permalink to “Скрипты Lua”">​</a></h1><p>Скрипты Lua позволяют гибко расширять Xray, реализовывать собственные функции и взаимодействовать с ядром.</p><h2 id="начало-работы" tabindex="-1">Начало работы <a class="header-anchor" href="#начало-работы" aria-label="Permalink to “Начало работы”">​</a></h2><p>Сначала прочитайте <a href="./environment.html">Среда выполнения и загрузка скриптов</a>, чтобы узнать о поддержке Lua, загрузке модулей и правилах поиска файлов скриптов.</p><h2 id="руководства-по-написанию" tabindex="-1">Руководства по написанию <a class="header-anchor" href="#руководства-по-написанию" aria-label="Permalink to “Руководства по написанию”">​</a></h2><p>Выберите руководство для нужной функции, начните с минимального примера и постепенно создайте собственный скрипт:</p><table tabindex="0"><thead><tr><th>Руководство</th><th>Назначение</th><th>Содержание</th></tr></thead><tbody><tr><td><a href="./guide/routing.html">Скрипты маршрутизации</a></td><td>Собственные правила маршрутизации</td><td>Выбор исходящего подключения, балансировка нагрузки и маршрутизация по IP после явного разрешения домена</td></tr><tr><td><a href="./guide/dns.html">Скрипты DNS</a></td><td>Собственная обработка DNS-запросов</td><td>Выбор вышестоящего сервера, резервные запросы и фильтрация результатов</td></tr></tbody></table><p>Текущие скрипты маршрутизации и DNS используют экземпляры из пула. При написании скриптов учитывайте <a href="./guide/lifecycle.html#жизненныи-цикл-пула">жизненный цикл пула</a>, чтобы понимать, когда выполняется инициализация верхнего уровня и как сохраняется состояние.</p><h2 id="справочник" tabindex="-1">Справочник <a class="header-anchor" href="#справочник" aria-label="Permalink to “Справочник”">​</a></h2><h3 id="hook" tabindex="-1">Hook <a class="header-anchor" href="#hook" aria-label="Permalink to “Hook”">​</a></h3><p>Hook — это функция Lua, которую ядро вызывает в определённый момент. Точка входа скрипта определяет доступные Hook и соглашения об их вызове; одной точке входа могут соответствовать несколько Hook. Какие именно Hook нужно реализовать, указано в описании соответствующей точки входа.</p><p>Сейчас поддерживаются следующие точки входа и Hook. Параметры, возвращаемые значения и поведение при ошибках описаны на справочных страницах каждого Hook:</p><table tabindex="0"><thead><tr><th>Точка входа скрипта</th><th>Hook</th></tr></thead><tbody><tr><td><code>routing.script</code></td><td><a href="./reference/hook-routing.html">HandleRoute</a></td></tr><tr><td><code>dns.script</code></td><td><a href="./reference/hook-dns.html">HandleDNSQuery</a></td></tr></tbody></table><h3 id="типы-данных" tabindex="-1">Типы данных <a class="header-anchor" href="#типы-данных" aria-label="Permalink to “Типы данных”">​</a></h3><p>Помимо встроенных типов Lua, Xray Lua использует <code>net.IP</code>, срезы Go и <code>error</code>. Их представление и способы работы с ними в Lua описаны в разделе <a href="./reference/data-types.html">Типы данных</a>.</p><h3 id="api-модулеи" tabindex="-1">API модулей <a class="header-anchor" href="#api-модулеи" aria-label="Permalink to “API модулей”">​</a></h3><p>Выберите API модуля по назначению:</p><table tabindex="0"><thead><tr><th>Модуль</th><th>Назначение</th></tr></thead><tbody><tr><td><a href="./reference/module-router.html">xray.router</a></td><td>Маршрутизация по правилам</td></tr><tr><td><a href="./reference/module-dns.html">xray.dns</a></td><td>Разрешение доменных имён</td></tr><tr><td><a href="./reference/module-geodata.html">xray.geodata</a></td><td>Сопоставление и фильтрация доменов и IP</td></tr><tr><td><a href="./reference/module-log.html">xray.log</a></td><td>Запись журналов</td></tr></tbody></table>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};